/* Glyph for a character code: ASCII, the extra icons, else '?'. */
static inline const uint8_t *jbm13_glyph(uint8_t ch) {
    if (ch >= JBM13_FIRST_ASCII && ch <= JBM13_LAST_ASCII)
        return font_jbm13[(JBM13_LAST_EXTRA - JBM13_FIRST_EXTRA + 1u) + (ch - JBM13_FIRST_ASCII)];
    if (ch >= JBM13_FIRST_EXTRA && ch <= JBM13_LAST_EXTRA)
        return font_jbm13[ch - JBM13_FIRST_EXTRA];
    return jbm13_glyph('?');
}

